//
// Fixes up all composite datatypes within the current program to account for 
// any changes to primitive datatype sizes or alignment rules as defined
// by the associated data organization.
//
// This script requires exclusive access to the program to avoid the possibilty
// of excessive change conflicts.
//
// This script can be run multiple times without harm
//@category Data Types


using ghidra.app.script;
using ghidra.app.services;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.program.database.data;
using ghidra.program.database.data;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.dtarchive;
using ghidra.program.model.listing;

public class FixupCompositeDataTypesScript : GhidraScript {

	/* @Override */
	protected void run()
    {

		PluginTool tool = state.getTool();
		if (tool == null) {
			print("This script does not support headless use");
		}

		DataTypeManagerService service = tool.getService(typeof(DataTypeManagerService));
		if (service == null) {
			popup("This script requires the DataTypeManagerService");
			return;
		}

		List<DTMWrapper> dtms = new();

		foreach (DataTypeManager dtm in service.getDataTypeManagers()) {
			if (dtm is BuiltInDataTypeManager) {
				continue;
			}
			if (dtm is DataTypeManagerDB dtmDB) {
				dtms.add(new DTMWrapper(dtmDB));
			}
		}

		DataTypeManagerDB dtm =
			askChoice("Fixup All Composites", "Select Data Type Manager: ", dtms, dtms.get(0)).dtm;

		if (dtm is ProgramDataTypeManager programDtm) {
			Program program = programDtm.getProgram();
			if (!program.hasExclusiveAccess()) {
				popup("Shared program must have an exclusive checkout.");
				return;
			}
		}
		else if (dtm.getDataStore() is ProjectDataTypeArchive projectArchive) {
			DomainFile df = projectArchive.getDomainFile();
			if (df.isVersioned() && !df.isCheckedOutExclusive()) {
				popup("Shared project archive must have an exclusive checkout.");
				return;
			}
		}

		if (!dtm.isUpdatable()) {
			popup("Selected archive must be open for update.");
			return;
		}
		dtm.fixupComposites(monitor);
	}

	private class DTMWrapper {
		DataTypeManagerDB dtm;

		DTMWrapper(DataTypeManagerDB dtm) {
			this.dtm = dtm;
		}

		/* @Override */
		public string toString() {
			return dtm.getName();
		}
	}

}
